const cfg = $('Config').first().json;
const page = $('Get General tools page').first().json;
const sheet = $('Get checklist sheet').first().json;

const WIDTH = 10;
const KEY = 8;
const NOTE = 9;
const HEADER_KEY = 'Sync key (General tools)';
const HEADER_NOTE = 'Sync note';
const NEW_PREFIX = 'New from General tools';
const ORPHAN_PREFIX = 'Not on General tools since';
const DUP_PREFIX = 'Duplicate sync key';
const today = $now.setZone('Europe/Zagreb').toFormat('yyyy-MM-dd');
const newNote = NEW_PREFIX + ' ' + today + ' - set Status, Priority and Owner';

// Confluence category -> existing checklist section (sheet sections are kept as they are)
const SECTION_MAP = {
  'communication & collaboration': 'Project Management',
  'project management': 'Project Management',
  'design&product': 'Design&Product',
  'engineering (dev, devops & qa)': 'Engineering (Dev, DevOps & QA)',
  'ai': 'Engineering (Dev, DevOps & QA)',
  'security': 'Security',
  'customer support': 'Customer Support',
  'payments': 'Payments',
  'marketing & advertising': 'Marketing & Others tools',
  'analytics & experimentation': 'Marketing & Others tools',
  'marketing & others tools': 'Marketing & Others tools',
  'hr': 'HHRR'
};

// One-time mapping for checklist rows whose name differs from General tools (approved 2026-09-24)
const ALIASES = {
  'slack grid': ['Slack workspace'],
  'microsoft (mail, calendar, onedrive)': ['Microsoft 365 (Mail, Calendar, OneDrive)'],
  'loom (video recorder)': ['Loom'],
  'fireflies.ai (confcalls ai summarizer)': ['Fireflies'],
  'zoom (confcalls)': ['Zoom'],
  'workboard (okrs - leadership team)': ['Workboard'],
  'flaticon or freepik (same company) - one time use tool': ['Flaticon', 'Freepik'],
  'untitledui (www.untitledui.com) - one time use tool (react components)': ['UntitledUI'],
  'okta (anual invocie, paid directly by transfer)': ["Okta (providing access to some tools + project's webpage access)"],
  'groundcover ($35usd per node under the plan we have now)': ['GroundCover'],
  'aircall': ['Aircall (IVR)'],
  'stripe access + rotate keys': ['Stripe']
};

function str(v) { return String(v === null || v === undefined ? '' : v).trim(); }
function norm(s) {
  return str(s).replace(/\u00a0/g, ' ').replace(/\(\s+/g, '(').replace(/\s+\)/g, ')').replace(/\s+/g, ' ').toLowerCase();
}
const INLINE = { paragraph: 1, heading: 1, text: 1 };
function nodeText(n) {
  if (!n) return '';
  if (n.type === 'text') return n.text || '';
  if (n.type === 'hardBreak') return ' ';
  if (n.type === 'inlineCard') return (n.attrs && n.attrs.url) || '';
  if (n.type === 'status' || n.type === 'mention' || n.type === 'emoji') return (n.attrs && (n.attrs.text || n.attrs.shortName)) || '';
  const parts = (n.content || []).map(nodeText);
  return INLINE[n.type] ? parts.join('') : parts.join(' ');
}
function findTable(n) {
  if (!n) return null;
  if (n.type === 'table') return n;
  for (const c of (n.content || [])) { const t = findTable(c); if (t) return t; }
  return null;
}

// ---- 1. Tools on the General tools page
const raw = page && page.body && page.body.atlas_doc_format && page.body.atlas_doc_format.value;
if (!raw) throw new Error('General tools page body (atlas_doc_format) is missing');
const adf = typeof raw === 'string' ? JSON.parse(raw) : raw;
const table = findTable(adf);
if (!table) throw new Error('No table found on the General tools page');
const conf = new Map();
let category = '';
let order = 0;
for (const row of (table.content || [])) {
  const cells = row.content || [];
  if (!cells.length || cells[0].type === 'tableHeader') continue;
  const first = nodeText(cells[0]).replace(/\s+/g, ' ').trim();
  if (!first) continue;
  const bg = String((cells[0].attrs && cells[0].attrs.background) || '').toLowerCase();
  const restEmpty = cells.slice(1).every(function (c) { return !nodeText(c).trim(); });
  if (bg === '#f4f5f7' || restEmpty) { category = first; continue; }
  const k = norm(first);
  if (!conf.has(k)) conf.set(k, { name: first, category: category, order: order++ });
