const cfg = $('Config').first().json;
const TAG = String(cfg.tag || '[internal]').toLowerCase();
const src = $('Get General tools page').first().json;
const pub = $('Get public page').first().json;

function result(action, extra) { return [{ json: Object.assign({ action: action }, extra) }]; }

