  }
  const hash = cyrb53(json);
  const lastMessage = String((pub.version && pub.version.message) || '');
  stats.hash = hash;
  stats.internalVersion = src.version && src.version.number;
  stats.publicVersion = pub.version.number;
  if (lastMessage.indexOf('[sync:' + hash + ']') !== -1) return result('unchanged', { stats: stats });

  const request = {
    id: String(cfg.publicPageId),
    status: 'current',
    title: pub.title,
    body: { representation: 'atlas_doc_format', value: json },
    version: { number: pub.version.number + 1, message: 'Synced from the internal page v' + stats.internalVersion + ' [sync:' + hash + ']' }
  };
  if (cfg.publicDryRun) return result('dryRun', { stats: stats, wouldPublishVersion: request.version.number, previewBytes: json.length });
  return result('publish', { stats: stats, request: request });
} catch (e) {
  return result('alert', { alertText: 'Public page not updated, the sync hit an error: ' + e.message });
}
